import base64, io, zipfile, json, re, hashlib
import xml.etree.ElementTree as ET
from difflib import SequenceMatcher

W = "{http://schemas.openxmlformats.org/wordprocessingml/2006/main}"


def read_clauses(b64):
    z = zipfile.ZipFile(io.BytesIO(base64.b64decode(b64)))
    root = ET.fromstring(z.read("word/document.xml"))
    clauses, current = [], None
    for p in root.iter(W + "p"):
        ppr = p.find(W + "pPr")
        style = None
        if ppr is not None:
            ps = ppr.find(W + "pStyle")
            if ps is not None:
                style = ps.get(W + "val")
        text = "".join(t.text or "" for t in p.iter(W + "t")).strip()
        if style == "Heading2":
            current = {"heading": text, "text": ""}
            clauses.append(current)
        elif style != "Heading1" and text and current is not None:
            current["text"] = (current["text"] + " " + text).strip()
    return clauses


def norm(h):
    return re.sub(r"^\s*\d+[\.\)]\s*", "", h).strip().lower()


def sim(a, b):
    return SequenceMatcher(None, a, b).ratio()


def doc_title(raw):
    xml = zipfile.ZipFile(io.BytesIO(raw)).read("word/document.xml").decode("utf-8")
    for para in xml.split("</w:p>"):
        text = ""
        for chunk in para.split("<w:t")[1:]:
            if chunk[:1] in (">", " "):
                text += chunk.split(">", 1)[1].split("</w:t>")[0]
        if text.strip():
            return text.strip()
    return ""


def base_title(t):
    t = t.lower().strip()
    for word in ("current", "previous"):
        if t.endswith(word):
            t = t[: -len(word)].rstrip(" -:()")
    return t


row = _items[0]["json"]

# I2: size and file type
MAX_BYTES = 15 * 1024 * 1024
for name in ("previous_b64", "current_b64"):
    raw = base64.b64decode(row[name])
    if len(raw) > MAX_BYTES:
        raise Exception("Rejected: " + name + " is larger than 15 MB")
    try:
        if "word/document.xml" not in zipfile.ZipFile(io.BytesIO(raw)).namelist():
            raise Exception("not a Word document")
    except Exception:
        raise Exception("Rejected: " + name + " is not a supported file type (DOCX only)")

# I6: both files must be versions of the same document
prev_title = base_title(doc_title(base64.b64decode(row["previous_b64"])))
curr_title = base_title(doc_title(base64.b64decode(row["current_b64"])))
if prev_title != curr_title:
    raise Exception("Rejected: the two files are not versions of the same document")

prev = read_clauses(row["previous_b64"])
curr = read_clauses(row["current_b64"])

pair_hash = hashlib.sha256(
    json.dumps({"previous": prev, "current": curr}, sort_keys=True, ensure_ascii=False).encode("utf-8")
).hexdigest()

for i, c in enumerate(prev):
    c["i"], c["n"] = i, norm(c["heading"])
for i, c in enumerate(curr):
    c["i"], c["n"] = i, norm(c["heading"])

# Phase 1: exact matches (same heading text and same body text)
mp, mc = {}, {}
pk, ck = {}, {}
for c in prev:
    pk.setdefault((c["n"], c["text"]), []).append(c["i"])
for c in curr:
    ck.setdefault((c["n"], c["text"]), []).append(c["i"])
for key, pl in pk.items():
    cl = ck.get(key)
    if cl:
        for a, b in zip(sorted(pl), sorted(cl)):
            mp[a], mc[b] = b, a

# Phase 2: fuzzy matches among the clauses left over
cands = []
for p in prev:
    if p["i"] in mp:
        continue
    for c in curr:
        if c["i"] in mc:
            continue
        score = 0.6 * sim(p["n"], c["n"]) + 0.4 * sim(p["text"], c["text"])
        if score >= 0.5:
            cands.append((score, p["i"], c["i"]))
cands.sort(reverse=True, key=lambda x: x[0])
for score, a, b in cands:
    if a in mp or b in mc:
        continue
    mp[a], mc[b] = b, a

# Classify every clause: unchanged / edited / moved / added / removed
entries = []
for p in prev:
    if p["i"] not in mp:
        entries.append({"heading": p["heading"], "status": "removed", "previous_text": p["text"], "current_text": None})
        continue
    c = curr[mp[p["i"]]]
    same_text, same_pos = p["text"] == c["text"], p["i"] == c["i"]
    if same_text and same_pos:
        status = "unchanged"
    elif same_text:
        status = "moved"
    elif same_pos:
        status = "edited"
    else:
        status = "moved"
    e = {"heading": c["heading"], "status": status, "previous_text": p["text"], "current_text": c["text"]}
    if status == "moved" and not same_text:
        e["also_edited"] = True
    entries.append(e)
for c in curr:
    if c["i"] not in mc:
        entries.append({"heading": c["heading"], "status": "added", "previous_text": None, "current_text": c["text"]})

# Only clauses whose TEXT changed go to the model (C3)
to_send = []
for position, e in enumerate(entries):
    if e["status"] == "unchanged" or (e["status"] == "moved" and not e.get("also_edited")):
        continue
    to_send.append((position, e))
skipped = len(entries) - len(to_send)

if not to_send:
    return [{"json": {"no_changes": True, "pair_hash": pair_hash,
                      "clauses_total": len(entries), "clauses_skipped": skipped}}]

return [{"json": {
    "position": position, "heading": e["heading"], "status": e["status"],
    "previous_text": e["previous_text"], "current_text": e["current_text"],
    "pair_hash": pair_hash, "clauses_total": len(entries), "clauses_skipped": skipped,
}} for position, e in to_send]

import json

LEVELS = ("High", "Medium", "Low")
out = []
for item in _items:
    d = dict(item["json"])
    raw = str(d.pop("raw_text", "") or "").strip()
    http_error = str(d.pop("http_error", "") or "")
    if http_error:
        res = {"risk_level": "Error", "reason": "API call failed: " + http_error[:150], "policy_rule_touched": "N/A"}
    else:
        raw = raw.replace("```json", "").replace("```", "").strip()
        try:
            res = json.loads(raw)
            if not isinstance(res, dict) or res.get("risk_level") not in LEVELS:
                raise ValueError("unexpected reply")
        except Exception:
            res = {"risk_level": "Unknown", "reason": "Could not parse model response: " + raw[:100],
                   "policy_rule_touched": "N/A"}
    d["risk_level"] = res["risk_level"]
    d["reason"] = str(res.get("reason", ""))
    d["policy_rule_touched"] = str(res.get("policy_rule_touched", "N/A"))
    if len(d["reason"]) > 200:
        d["c6_warning"] = "Reason field unusually long - possible clause rewrite, review manually."
    out.append({"json": d})
return out

