const pack = $('Build pack').first().json;
const rows = $('Parse reply').all().map(i => i.json);
const failed = pack.error_queue || [];

const hex = n => Array.from({ length: n }, () => Math.floor(Math.random() * 16).toString(16)).join('');
const traceId = hex(32);
const rootId = hex(16);
const nowNs = String(BigInt(Date.now()) * 1000000n);

const s = (key, value) => ({ key, value: { stringValue: String(value) } });
const arr = (key, values) => ({ key, value: { arrayValue: { values: values.map(v => ({ stringValue: String(v) })) } } });

const tags = ['contract-review', 'prompt:' + pack.prompt_version, 'model:' + pack.model, 'status:' + pack.status];
const complete = pack.status === 'complete';

const spans = [];

// Parent span: one per document pair, session id = pair hash
spans.push({
  traceId, spanId: rootId, name: 'contract-review',
  kind: 1, startTimeUnixNano: nowNs, endTimeUnixNano: nowNs,
  attributes: [
    s('langfuse.observation.type', 'span'),
    s('langfuse.trace.name', 'contract-review'),
    s('langfuse.session.id', pack.pair_hash),
    arr('langfuse.trace.tags', tags),
    s('langfuse.observation.input', 'pair_hash=' + pack.pair_hash + ' prompt_version=' + pack.prompt_version),
    s('langfuse.observation.output', JSON.stringify({
      status: pack.status,
      changed_clauses: pack.changed_clauses,
      risk_mix: pack.risk_mix,
      human_queue: (pack.human_queue || []).length,
      failed_clauses: failed.length
    })),
    s('langfuse.observation.metadata.pair_hash', pack.pair_hash),
    s('langfuse.observation.metadata.prompt_version', pack.prompt_version)
  ],
  status: { code: complete ? 1 : 2 }
});

// One child span per classified clause
for (const r of rows) {
  spans.push({
    traceId, spanId: hex(16), parentSpanId: rootId,
    name: 'clause: ' + r.heading,
    kind: 1, startTimeUnixNano: nowNs, endTimeUnixNano: nowNs,
    attributes: [
      s('langfuse.observation.type', 'generation'),
      s('langfuse.observation.model.name', pack.model),
      s('langfuse.observation.usage_details', JSON.stringify({ input: r.input_tokens || 0, output: r.output_tokens || 0 })),
      s('langfuse.observation.input', 'heading=' + r.heading + ' position=' + r.position),
      s('langfuse.observation.output', JSON.stringify({ risk_level: r.risk_level })),
      s('langfuse.observation.metadata.risk_level', r.risk_level),
      s('langfuse.observation.metadata.prompt_version', pack.prompt_version)
    ],
    status: { code: 1 }
  });
}

// One child span per failed clause
for (const f of failed) {
  spans.push({
    traceId, spanId: hex(16), parentSpanId: rootId,
    name: 'clause failed: ' + (f.clause_ref || f.heading || 'unknown'),
    kind: 1, startTimeUnixNano: nowNs, endTimeUnixNano: nowNs,
    attributes: [
      s('langfuse.observation.type', 'span'),
      s('langfuse.observation.level', 'ERROR'),
      s('langfuse.observation.metadata.error', 'model call failed')
    ],
    status: { code: 2 }
  });
}

return [{
  json: {
    resourceSpans: [{
      resource: { attributes: [s('service.name', 'n8n-contract-review')] },
      scopeSpans: [{ scope: { name: 'contract-review' }, spans }]
    }]
  }
}];

const pack = $('Build pack').first().json;
const queue = pack.human_queue || [];

return queue.map(q => ({
  json: {
    pair_hash: pack.pair_hash,
    clause_ref: q.heading || q.clause_ref || q.clause || '',
    reason: q.reason || q.risk_reason || q.rationale || 'High risk',
    reviewed: false
  }
}));

const pack = $('Build pack').first().json;
const first = $('Code in Python').first().json;

const IN_PRICE = 1.38;   // USD per 1M input tokens (confirm for your deployment)
const OUT_PRICE = 11.00; // USD per 1M output tokens

const total = first.clauses_total ?? 0;
const skipped = first.clauses_skipped ?? 0;
const inTok = pack.input_tokens ?? 0;
const outTok = pack.output_tokens ?? 0;
const table = pack.change_table ?? [];
const failed = (pack.error_queue ?? []).length;

return [{
  json: {
    pair_hash: first.pair_hash,
    clauses_total: total,
    clauses_sent: table.length,
    clauses_skipped: skipped,
    input_tokens: inTok,
    output_tokens: outTok,
    cost_usd: Number(((inTok * IN_PRICE + outTok * OUT_PRICE) / 1e6).toFixed(6)),
    failed_clauses: failed,
    duplicate: false
  }
}];
